import java.util.*;

public class Main {
    class NumberContainers {
        Map<Integer, Integer> indexToNum = new HashMap<>();                          // a plain map: index -> current number there

        void change(int index, int number) {
            indexToNum.put(index, number);
        }

        int find(int number) {
            int best = Integer.MAX_VALUE;
            for (Map.Entry<Integer, Integer> e : indexToNum.entrySet()) {               // rescan EVERYTHING every single find() call
                if (e.getValue() == number) best = Math.min(best, e.getKey());
            }
            return best == Integer.MAX_VALUE ? -1 : best;
        }
    }

    public static void main(String[] args) {
        NumberContainers nc = new NumberContainers();
        nc.change(2, 10);
        nc.change(1, 10);
        System.out.println(nc.find(10));
        nc.change(1, 20);
        System.out.println(nc.find(10));
    }
}

