import java.util.*;

public class Main {
    class NumberContainers {
        Map<Integer, Integer> indexToNum = new HashMap<>();                             // the SOURCE OF TRUTH: what number is CURRENTLY at each index
        Map<Integer, PriorityQueue<Integer>> numToHeap = new HashMap<>();                  // a min-heap of indices per number (may contain STALE entries)

        void change(int index, int number) {
            indexToNum.put(index, number);
            numToHeap.computeIfAbsent(number, k -> new PriorityQueue<>()).offer(index);       // just push; never bother removing the OLD number's stale entry
        }

        int find(int number) {
            PriorityQueue<Integer> heap = numToHeap.get(number);
            if (heap == null) return -1;
            while (!heap.isEmpty() && !Objects.equals(indexToNum.get(heap.peek()), number)) {    // lazily discard indices that no longer hold this number
                heap.poll();
            }
            return heap.isEmpty() ? -1 : heap.peek();
        }
    }

    public static void main(String[] args) {
        NumberContainers nc = new NumberContainers();
        nc.change(2, 10);
        nc.change(1, 10);
        System.out.println(nc.find(10));
        nc.change(1, 20);
        System.out.println(nc.find(10));
    }
}

