#include <bits/stdc++.h>
using namespace std;

class NumberContainers {
public:
    unordered_map<int, int> indexToNum;                                                       // the SOURCE OF TRUTH: what number is CURRENTLY at each index
    unordered_map<int, priority_queue<int, vector<int>, greater<int>>> numToHeap;                 // a min-heap of indices per number (may contain STALE entries)

    void change(int index, int number) {
        indexToNum[index] = number;
        numToHeap[number].push(index);                                                              // just push; never bother removing the OLD number's stale entry
    }

    int find(int number) {
        if (!numToHeap.count(number)) return -1;
        auto& heap = numToHeap[number];
        while (!heap.empty() && indexToNum[heap.top()] != number) {                                     // lazily discard indices that no longer hold this number
            heap.pop();
        }
        return heap.empty() ? -1 : heap.top();
    }
};

int main() {
    NumberContainers nc;
    nc.change(2, 10);
    nc.change(1, 10);
    cout << nc.find(10) << endl;
    nc.change(1, 20);
    cout << nc.find(10) << endl;
    return 0;
}
